import { CommonModule, DOCUMENT } from "@angular/common";
import {
  inject,
  Component,
  ViewChild,
  ChangeDetectionStrategy,
  HostListener,
} from "@angular/core";
import { FormsModule } from "@angular/forms";
import { RouterModule } from "@angular/router";

import { AvatarModule } from "primeng/avatar";
import { ButtonModule } from "primeng/button";
import { RippleModule } from "primeng/ripple";
import { PanelMenuModule } from "primeng/panelmenu";
import { StyleClassModule } from "primeng/styleclass";
import { InputSwitchModule } from "primeng/inputswitch";
import { Sidebar, SidebarModule } from "primeng/sidebar";

import { AuthService } from "../../../auth/services/auth.service";

const primengModules = [
  AvatarModule,
  ButtonModule,
  RippleModule,
  SidebarModule,
  PanelMenuModule,
  StyleClassModule,
  InputSwitchModule,
];

interface MenuItem {
  label: string;
  icon?: string;
  items?: MenuItem[];
  badge?: string;
  routerLink?: string;
}

@Component({
  selector: "app-sidebar",
  standalone: true,
  imports: [...primengModules, RouterModule, FormsModule, CommonModule],
  templateUrl: "./sidebar.component.html",
  styleUrl: "./sidebar.component.css",
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class SidebarComponent {
  isDarkMode = false;
  visible: boolean = true;
  isExpanded: boolean = false;
  sidebarVisible: boolean = false;
  #document = inject(DOCUMENT);

  @ViewChild("sidebarRef") sidebarRef!: Sidebar;

  private authService = inject(AuthService);

  onInit() {
    this.toggleLightDark();
  }

  menuItems: MenuItem[] = [
    {
      label: "FAVORITES",
      items: [
        { label: "Dashboard", icon: "pi pi-home", routerLink: "/dashboard" },
        {
          label: "Bookmarks",
          icon: "pi pi-bookmark",
          routerLink: "/bookmarks",
        },
        {
          label: "Reports",
          icon: "pi pi-chart-line",
          items: [
            {
              label: "Revenue",
              icon: "pi pi-chart-line",
              items: [
                {
                  label: "View",
                  icon: "pi pi-table",
                  routerLink: "/reports/revenue/view",
                },
                {
                  label: "Search",
                  icon: "pi pi-search",
                  items: [
                    {
                      label: "Filters",
                      icon: "pi pi-filter",
                      items: [
                        {
                          label: "Date",
                          icon: "pi pi-calendar",
                          routerLink: "/reports/revenue/search/filters/date",
                        },
                      ],
                    },
                  ],
                },
              ],
            },
            {
              label: "Expenses",
              icon: "pi pi-chart-line",
              routerLink: "/reports/expenses",
            },
          ],
        },
        { label: "Team", icon: "pi pi-users", routerLink: "/team" },
        {
          label: "Messages",
          icon: "pi pi-comments",
          badge: "3",
          routerLink: "/messages",
        },
        { label: "Calendar", icon: "pi pi-calendar", routerLink: "/calendar" },
        { label: "Settings", icon: "pi pi-cog", routerLink: "/settings" },
      ],
    },
    {
      label: "APPLICATION",
      items: [
        { label: "Projects", icon: "pi pi-folder", routerLink: "/projects" },
        {
          label: "Performance",
          icon: "pi pi-chart-bar",
          routerLink: "/performance",
        },
        {
          label: "Settings",
          icon: "pi pi-cog",
          routerLink: "/application-settings",
        },
      ],
    },
  ];

  closeCallback(e: Event): void {
    this.sidebarRef.close(e);
  }

  logout() {
    this.authService.logout();
  }

  @HostListener("window:keydown", ["$event"])
  handleKeyboardEvent(event: KeyboardEvent) {
    if ((event.metaKey || event.ctrlKey) && event.key === "b") {
      this.sidebarVisible = !this.sidebarVisible;
      event.preventDefault();
    }
  }

  toggleLightDark() {
    const linkElement = this.#document.getElementById(
      "app-theme",
    ) as HTMLLinkElement;
    if (linkElement.href.includes("light")) {
      linkElement.href = "dark.css";
      this.isDarkMode = true;
    } else {
      linkElement.href = "light.css";
      this.isDarkMode = false;
    }
  }
}
